function nxProjectsPage(){return `<div class="nx-workspace-welcome"><div><span class="nx-section-tag">Acme workspace</span><h1>Your projects, in perspective.</h1><p>A home for every customer journey. Pick a project and explore what connects.</p></div><button class="nx-button primary small" data-action="new-site">${nxIcon('website',16)} Explore templates</button></div><div class="nx-workspace-summary"><div><span class="nx-summary-icon">${nxIcon('projects',20)}</span><div><strong>4</strong><span>Project concepts</span></div></div><div><span class="nx-summary-icon">${nxIcon('workflows',20)}</span><div><strong>7</strong><span>Connected modules</span></div></div><div><span class="nx-summary-icon">${nxIcon('shield',20)}</span><div><strong>Preview</strong><span>Your frontend blueprint</span></div></div><button data-page="home">Discover the Nexus story ${nxIcon('arrow',17)}</button></div><div class="nx-workspace-project-heading"><div><h2>All projects</h2><p>Illustrative examples for your next business.</p></div><div class="nx-grid-toggle"><button aria-pressed="${nxView==='grid'}" class="${nxView==='grid'?'active':''}" data-project-view="grid" aria-label="Grid view">${nxIcon('projects',16)}</button><button aria-pressed="${nxView==='list'}" class="${nxView==='list'?'active':''}" data-project-view="list" aria-label="List view">☰</button></div></div><div class="nx-workspace-project-controls"><div class="nx-filter-tabs">${['All projects','SaaS','Agency','Education'].map(n=>`<button class="${nxProjectFilter===n?'selected':''}" data-project-filter="${n}" aria-pressed="${nxProjectFilter===n}">${n}</button>`).join('')}</div><label class="nx-project-search">${nxIcon('search',16)}<input type="search" id="project-search" placeholder="Find a project" aria-label="Find a project"></label></div><div class="nx-project-grid ${nxView==='list'?'list-view':''}" id="workspace-project-grid">${nxProjectCards(nxProjectFilter,true)}</div><div class="nx-project-empty" hidden><span>${nxIcon('search',25)}</span><h3>No matching projects</h3><p>Try another name or category.</p><button class="nx-text-button" data-clear-project-search>Clear search</button></div><div class="nx-workspace-bottom"><span>${nxIcon('shield',14)} Example projects. No live customer data.</span><span>Everything starts with a connected workspace.</span></div>`}
function nxProjectDetail(id){const p=nxProjects.find(x=>x.id===id);if(!p)return;modal(`${p.name}. Project concept`,`${nxProjectCover(p)}<div class="nx-project-detail"><span class="nx-section-tag">${p.category} concept</span><h3>${p.line}</h3><p>${p.desc}</p><div class="nx-project-detail-modules">${p.modules.map(m=>`<span>${nxIcon(m==='Website'?'website':m==='CRM'?'crm':m==='Webinars'?'webinars':m==='Billing'?'billing':'campaigns',16)}${m}</span>`).join('')}</div><h4>A connected project blueprint</h4><div class="nx-project-detail-steps"><div><span>1</span><p><strong>Build the first impression</strong>A template-based website shaped around ${p.category==='Agency'?'the studio’s work':p.category==='Education'?'the learning experience':'the product'}.</p></div><div><span>2</span><p><strong>Keep the relationship in context</strong>Inquiries and interactions appear together in a shared customer view.</p></div><div><span>3</span><p><strong>Make the next step visible</strong>${p.modules.includes('Billing')?'Explore the subscription and revenue layouts.':'Preview relevant events and follow-up conversations.'}</p></div></div><p class="nx-concept-detail-note">Design example. All brand names, projects, and data in this showcase are illustrative.</p></div>`,btn('Explore website editor','go-builder',true)+btn('Open connected CRM','go-crm'));}
const nxOriginalContent=renderContent;
renderContent=function(){if(page==='projects'){document.getElementById('content').innerHTML=nxProjectsPage();}else nxOriginalContent();};
const nxOriginalRender=render;
render=function(){document.body.classList.toggle('marketing-page',page==='home');document.body.classList.toggle('workspace-page',page!=='home');if(page==='home')return renderHome();nxOriginalRender();};
function nxFilterProjects(){const q=document.getElementById('project-search')?.value.toLowerCase()||'';document.querySelectorAll('#workspace-project-grid .nx-project-card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));const visible=[...document.querySelectorAll('#workspace-project-grid .nx-project-card')].some(c=>!c.hidden);const empty=document.querySelector('.nx-project-empty');if(empty)empty.hidden=visible;}
document.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('.nx-header')?.classList.remove('menu-open');document.querySelector('[data-home-menu]')?.setAttribute('aria-expanded','false');if(scroll.classList.contains('nx-skip'))document.getElementById('main-story')?.focus({preventScroll:true});}const project=e.target.closest('[data-project]');if(project)nxProjectDetail(project.dataset.project);const f=e.target.closest('[data-project-filter]');if(f){nxProjectFilter=f.dataset.projectFilter;if(page==='home'){document.querySelectorAll('[data-project-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.projectFilter===nxProjectFilter);b.setAttribute('aria-pressed',b.dataset.projectFilter===nxProjectFilter)});document.getElementById('showcase-grid').innerHTML=nxProjectCards(nxProjectFilter)}else{const val=document.getElementById('project-search')?.value;renderContent();if(val)document.getElementById('project-search').value=val;nxFilterProjects();}}const step=e.target.closest('[data-journey]');if(step){nxStep=+step.dataset.journey;document.querySelectorAll('[data-journey]').forEach(b=>{b.classList.toggle('current',+b.dataset.journey===nxStep);b.setAttribute('aria-selected',+b.dataset.journey===nxStep);b.tabIndex=+b.dataset.journey===nxStep?0:-1});const panel=document.getElementById('journey-panel');panel.innerHTML=nxJourneyScene();panel.setAttribute('aria-labelledby',`journey-tab-${nxStep}`)}const view=e.target.closest('[data-project-view]');if(view){nxView=view.dataset.projectView;renderContent()}if(e.target.closest('[data-clear-project-search]')){document.getElementById('project-search').value='';nxFilterProjects()}const menu=e.target.closest('[data-home-menu]');if(menu){const open=document.querySelector('.nx-header').classList.toggle('menu-open');menu.setAttribute('aria-expanded',open)}});
document.addEventListener('input',e=>{if(e.target.id==='project-search')nxFilterProjects()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-journey]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=+e.target.dataset.journey;i=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:-1)+5)%5;const next=document.querySelector(`[data-journey="${i}"]`);next.click();next.focus()}if(e.key==='Escape'){document.querySelector('.nx-header')?.classList.remove('menu-open');document.querySelector('[data-home-menu]')?.setAttribute('aria-expanded','false')}});
render();
